    ("unsigned-is-bogus", "Every unsigned answer is DNSSEC Bogus", "An authenticated insecure delegation can legitimately lead to Insecure data; Bogus means required authentication failed under the applicable chain and policy.", "insecure"),
    ("stun-guarantees-p2p", "A STUN address guarantees a peer can connect", "STUN reports an endpoint observed on one exchange; mapping dependence, filtering, expiration, firewalls, and different paths can prevent peers from using it.", "observed-endpoint"),
    ("mapping-equals-filter", "Endpoint-independent mapping means unrestricted inbound packets", "Mapping reuse and inbound filtering are separate NAT behaviors; a reusable external tuple can still accept traffic only from previously contacted peers.", "independent-mapping"),
    ("nat-is-encryption", "NAT translation encrypts peer traffic", "Changing address and port fields does not encrypt the application payload; transport confidentiality requires a separate protection mechanism.", "nat-mapping"),
    ("offer-is-lease", "A DHCP offer authorizes immediate address use", "An offer is a proposal; initial lease use follows the selected allocation acknowledgment and applicable client conflict checks.", "dhcp-offer"),
